import SwiftUI
import KachiiroCore

/// Conjugation chart and plain/polite matrix generated by the engines.
struct ConjugationReferenceView: View {
    var body: some View {
        ScrollView([.horizontal, .vertical]) {
            VStack(alignment: .leading, spacing: 28) {
                verbChart
                matrix
            }
            .padding()
        }
        .background(AppTheme.canvas)
        .navigationTitle("Reference")
        .navigationBarTitleDisplayMode(.inline)
    }

    private var verbChart: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("動詞の活用").font(AppTheme.Fonts.ui(.headline))
            Grid(alignment: .leading, horizontalSpacing: 14, verticalSpacing: 8) {
                GridRow {
                    Text("")
                    ForEach(VerbForm.allCases, id: \.self) { form in
                        Text(form.shortLabel).font(.caption.bold()).foregroundStyle(AppTheme.accent)
                    }
                }
                Divider()
                ForEach(ConjugationReference.verbs, id: \.headword) { lexeme in
                    GridRow {
                        Text(lexeme.headword).font(.body.bold())
                        ForEach(Array(ConjugationReference.verbRow(lexeme).enumerated()), id: \.offset) { _, cell in
                            Text(cell).font(.callout)
                        }
                    }
                }
            }
        }
    }

    private var matrix: some View {
        VStack(alignment: .leading, spacing: 8) {
            Text("丁寧形・普通形").font(AppTheme.Fonts.ui(.headline))
            Grid(alignment: .leading, horizontalSpacing: 14, verticalSpacing: 8) {
                GridRow {
                    Text("")
                    ForEach(InflectionCell.all, id: \.raw) { cell in
                        Text(cell.shortLabel).font(.caption.bold()).foregroundStyle(AppTheme.accent)
                    }
                }
                Divider()
                ForEach(ConjugationReference.matrixLexemes, id: \.title) { row in
                    GridRow {
                        Text(row.title).font(.body.bold())
                        ForEach(Array(ConjugationReference.matrixRow(row.lexeme).enumerated()), id: \.offset) { _, cell in
                            Text(cell).font(.callout)
                        }
                    }
                }
            }
        }
    }
}
